import {leafExchangeCopy as T,leafExchangeTrails,leafExchangeTeaching} from './leaf-exchange-content.mjs';
import {changeLeafExchange,leafExchangeModel,leafExchangeNarration} from './leaf-exchange-core.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value='',extra='')=>`<button type="button" data-leaf-exchange-action="${action}" data-leaf-exchange-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
const select=(action,label,value,options)=>`<label class="leaf-exchange-select"><span>${esc(label)}</span><select data-leaf-exchange-action="${action}">${options.map((o,i)=>`<option value="${o.value??i}"${(o.value??i)===value?' selected':''}>${esc(o.label??o.title)}</option>`).join('')}</select></label>`;
const signed=n=>n>0?`+${n}`:n<0?`−${Math.abs(n)}`:'0';
function chip(x,y,row){return `<g class="leaf-exchange-chip" data-leaf-exchange-chip="${row}"><rect x="${x-32}" y="${y-29}" width="64" height="58" rx="10"/>${[-10,10].map(dy=>[-16,0,16].map(dx=>`<circle cx="${x+dx}" cy="${y+dy}" r="6"/>`).join('')).join('')}</g>`;}
function ledger(photo,resp,paired=false,net=null){const numberLine=net!==null;return `<svg class="leaf-exchange-ledger" data-leaf-exchange-ledger viewBox="0 0 640 ${numberLine?330:245}" aria-hidden="true" focusable="false"><path class="leaf-exchange-rule" d="M24 122H616M24 244H616"/>${paired?Array.from({length:Math.min(photo,resp)},(_,i)=>`<line class="leaf-exchange-link" data-leaf-exchange-link x1="${70+100*i}" x2="${70+100*i}" y1="104" y2="171"/>`).join(''):''}${Array.from({length:photo},(_,i)=>chip(70+100*i,75,'photosynthesis')).join('')}${Array.from({length:resp},(_,i)=>chip(70+100*i,200,'respiration')).join('')}${numberLine?`<line class="leaf-exchange-axis" x1="68" x2="572" y1="285" y2="285"/>${Array.from({length:13},(_,i)=>`<line class="leaf-exchange-tick" x1="${68+42*i}" x2="${68+42*i}" y1="280" y2="290"/>`).join('')}<line class="leaf-exchange-pin" data-leaf-exchange-pin x1="${320+7*net}" x2="${320+7*net}" y1="276" y2="294"/>`:''}</svg>`;}
function lineKey(){return `<div class="leaf-exchange-line-key" aria-label="Number line values from negative to positive">${[-36,-24,-12,0,12,24,36].map(n=>`<span>${signed(n)}</span>`).join('')}</div>`;}
function rowCaptions(m){return `<div class="leaf-exchange-row-captions">${m.rows.map(r=>`<p data-leaf-exchange-row="${r.process}">${esc(r.caption)}</p>`).join('')}</div>`;}
function counter(work,key,label){return `<section class="leaf-exchange-counter">${select(key,`${label} groups`,work[key],Array.from({length:7},(_,i)=>({value:i,label:String(i)})))}<div class="leaf-exchange-actions">${button(key,`${label} −1`,work[key]-1,`data-leaf-exchange-direction="minus"${work[key]===0?' disabled':''}`)}${button(key,`${label} +1`,work[key]+1,`data-leaf-exchange-direction="plus"${work[key]===6?' disabled':''}`)}</div></section>`;}
function build(work,m){return `<h2 id="leaf-exchange-page-title" tabindex="-1">${esc(T.build)}</h2><p>${esc(T.buildInstruction)}</p><div class="leaf-exchange-counters">${counter(work,'photo','Photosynthesis')}${counter(work,'resp','Respiration')}</div><div class="leaf-exchange-actions" aria-label="Gas view">${button('gas','Oxygen','oxygen',`aria-pressed="${work.gas==='oxygen'}"`)}${button('gas','Carbon dioxide','carbon-dioxide',`aria-pressed="${work.gas==='carbon-dioxide'}"`)}</div><section class="leaf-exchange-paper"><h3>${esc(m.gasLabel)} accounts</h3>${rowCaptions(m)}${ledger(work.photo,work.resp,work.paired,m.net)}${lineKey()}<div class="leaf-exchange-results"><p data-leaf-exchange-net><strong>${esc(m.netCaption)}</strong></p><p>${esc(m.explanation)}</p><p data-leaf-exchange-other-net>${esc(m.otherNetCaption)}</p></div></section><div class="leaf-exchange-key"><svg viewBox="0 0 80 74" width="80" height="74" aria-hidden="true" focusable="false">${chip(40,37,'key')}</svg><p>${esc(T.chipKey)}</p></div><div class="leaf-exchange-pair">${button('pair','Pair opposite entries','',`aria-pressed="${work.paired}"`)}<p data-leaf-exchange-link-caption>${esc(m.linkCaption)}</p><p>${esc(T.pairNote)}</p></div><section class="leaf-exchange-trail">${select('trail','Choose a comparison to try',work.trail,leafExchangeTrails)}<h3>${esc(m.trail.title)}</h3><p>${esc(m.trail.prompt)}</p></section>`;}
function workedRows(photo,resp){return `<div class="leaf-exchange-row-captions"><p>Photosynthesis: ${photo} ${photo===1?'group':'groups'} · ${6*photo} oxygen molecules made.</p><p>Respiration: ${resp} ${resp===1?'group':'groups'} · ${6*resp} oxygen molecules used.</p></div>`;}
function workedFigure(lesson){if(lesson===0)return `${workedRows(1,1)}${ledger(1,1)}<table class="leaf-exchange-table"><caption>Both gas accounts for one group from each process</caption><thead><tr><th>Process</th><th>Oxygen</th><th>Carbon dioxide</th></tr></thead><tbody><tr><th>Photosynthesis</th><td>6 made</td><td>6 used</td></tr><tr><th>Respiration</th><td>6 used</td><td>6 made</td></tr></tbody></table>`;
if(lesson===1)return `${workedRows(3,1)}${ledger(3,1,true,12)}${lineKey()}<p>Oxygen net: +12 molecules. Carbon dioxide net: −12 molecules.</p>`;
if(lesson===2)return `<div class="leaf-exchange-examples"><section><h4>No entries · oxygen net: 0 molecules</h4>${workedRows(0,0)}${ledger(0,0)}</section><section><h4>Two groups each · oxygen net: 0 molecules</h4>${workedRows(2,2)}${ledger(2,2)}</section></div>`;
return `<div class="leaf-exchange-row-captions"><p>Left to right: 8 crossings.</p><p>Right to left: 5 crossings.</p></div><svg class="leaf-exchange-tray" data-leaf-exchange-tray viewBox="0 0 360 120" aria-hidden="true" focusable="false">${[8,5].map((count,row)=>Array.from({length:count},(_,i)=>`<rect x="${45+26*i}" y="${25+50*row}" width="22" height="22"/>`).join('')).join('')}</svg><p>One square = one crossing. Net: 3 markers left to right.</p>`;
}
function copied(work,m){const c=m.copied;if(!c)return `<p data-leaf-exchange-no-copy>${esc(T.noCopy)}</p>`;return `<section class="leaf-exchange-copy" data-leaf-exchange-copy><h3>${esc(c.heading)}</h3><p>${esc(c.note)}</p><p>${esc(c.identity)}</p>${c.kindOptions.length>1?select('kind','Choose a marker kind',work.kind,c.kindOptions.map(o=>({value:o.index,label:o.label}))):''}<p data-leaf-exchange-kind>${esc(c.label)}</p><p>${esc(c.permission)}</p><p>${esc(c.stepCaption)}</p><p>${esc(c.crossingsCaption)}</p><p data-leaf-exchange-copy-net>${esc(c.netCaption)}</p>${c.notice?`<details><summary>About this kept model</summary><p>${esc(c.notice)}</p></details>`:''}<p class="leaf-exchange-question">${esc(c.question)}</p></section>`;}
function learn(work,m){const t=m.teaching;return `<h2 id="leaf-exchange-page-title" tabindex="-1">${esc(T.learn)}</h2><div class="leaf-exchange-card-picker">${select('lesson','Choose a teaching card',work.lesson,leafExchangeTeaching)}<div class="leaf-exchange-actions">${button('lesson','Previous',work.lesson-1,work.lesson===0?'disabled':'')}${button('lesson','Next',work.lesson+1,work.lesson===3?'disabled':'')}</div></div><article class="leaf-exchange-teaching"><p class="leaf-exchange-eyebrow">${esc(T.workedLabel)}</p><h3 id="leaf-exchange-card-title" tabindex="-1">${esc(t.title)}</h3><p>${esc(t.text)}</p><figure class="leaf-exchange-paper">${workedFigure(work.lesson)}<figcaption>${esc(t.caption)}</figcaption></figure>${work.lesson===3?copied(work,m):''}</article><details class="leaf-exchange-destinations"><summary>Where this idea goes</summary><p id="leaf-exchange-leave-warning">${esc(T.leaveWarning)}</p><a href="#living/bodies" aria-describedby="leaf-exchange-leave-warning">Body clues → A leaf’s two accounts</a><a href="#science/ice" aria-describedby="leaf-exchange-leave-warning">Ice and warmth → Diffusion Tray</a></details>`;}
export function leafExchangePage(work,context){const m=leafExchangeModel(work,context);return `<div class="leaf-exchange-page" data-leaf-exchange-root><header><div class="leaf-exchange-actions">${button('back','Back to Living Layers')}<button type="button" data-leaf-exchange-hear data-speak="">Hear this page</button></div><p class="leaf-exchange-eyebrow">The gardener’s paper exhibit</p><h1 id="leaf-exchange-title" tabindex="-1">${esc(T.title)}</h1><p>${esc(T.story)}</p></header><nav class="leaf-exchange-actions" aria-label="Leaf Exchange pages">${['build','learn'].map(p=>button('page',T[p],p,`aria-pressed="${work.page===p}"`)).join('')}</nav>${m.page==='build'?build(work,m):learn(work,m)}<aside class="leaf-exchange-model-note"><p>${esc(T.modelNote)}</p><p>${esc(T.limitNote)}</p></aside><footer><p>${esc(T.visitNote)}</p></footer></div>`;}
export function bindLeafExchange(work,context,ctx){const root=document.querySelector('[data-leaf-exchange-root]');if(!root)return;const numeric=new Set(['photo','resp','trail','lesson','kind']);
const act=(node,event)=>{if(!ctx.live(node)||node.disabled){event.preventDefault();event.stopImmediatePropagation();return;}if(node.matches('summary'))return;ctx.stopSpeech();ctx.stopSound();if(node.matches('a'))return;if(node.hasAttribute('data-leaf-exchange-hear')){node.dataset.speak=leafExchangeNarration(work,context);return;}event.preventDefault();const action=node.dataset.leafExchangeAction;if(action==='back'){ctx.back();return;}let value=node.matches('select')?node.value:node.dataset.leafExchangeValue;if(numeric.has(action))value=Number(value);const next=changeLeafExchange(work,action,value,context);if(next===work)return;ctx.change(next);ctx.render();let focus;if(action==='page')focus='#leaf-exchange-page-title';else if(node.matches('select'))focus=`select[data-leaf-exchange-action="${action}"]`;else if(action==='photo'||action==='resp'){let direction=node.dataset.leafExchangeDirection;if(next[action]===0)direction='plus';if(next[action]===6)direction='minus';focus=`button[data-leaf-exchange-action="${action}"][data-leaf-exchange-direction="${direction}"]`;}else if(action==='lesson')focus='#leaf-exchange-card-title';else focus=`button[data-leaf-exchange-action="${action}"][data-leaf-exchange-value="${CSS.escape(node.dataset.leafExchangeValue)}"]`;ctx.focus(focus);};
root.querySelectorAll('button,a,summary').forEach(node=>node.addEventListener('click',event=>act(node,event),{capture:true}));root.querySelectorAll('select').forEach(node=>{node.addEventListener('click',event=>{if(!ctx.live(node)){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});node.addEventListener('change',event=>act(node,event),{capture:true});});}
